package org.familysearch.tree.memories

import org.junit.Assert.assertEquals
import org.junit.Test

class MemoriesViewModelTest {
    @Test
    fun memoryDeleted_dropsCachedList() {
        val repo = FakeMemoriesRepository(mutableListOf(Memory("m1"), Memory("m2")))
        val viewModel = MemoriesViewModel(repo)
        viewModel.load("KWCB-HZ2")
        repo.items.removeAt(0)
        viewModel.memoryDeleted("KWCB-HZ2")
        assertEquals(listOf(Memory("m2")), viewModel.load("KWCB-HZ2"))
    }
}
